messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Low-poly humanoid walk/run cycle</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #111;
            font-family: Arial, Helvetica, sans-serif;
        }
        canvas {
            display: block;
        }
        .info {
            position: absolute;
            bottom: 20px;
            left: 20px;
            color: #aaa;
            font-size: 14px;
            background: rgba(0,0,0,0.5);
            padding: 6px 12px;
            border-radius: 6px;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div class="info">stand → walk → run → stand (10s loop)</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Setup scene, camera, renderer ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a2e);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(6, 2.5, 8);
        camera.lookAt(0, 1.2, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lights ---
        const ambient = new THREE.AmbientLight(0x404060);
        scene.add(ambient);

        const dirLight = new THREE.DirectionalLight(0xffeedd, 1.2);
        dirLight.position.set(5, 8, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 512;
        dirLight.shadow.mapSize.height = 512;
        scene.add(dirLight);

        const fillLight = new THREE.DirectionalLight(0x4466ff, 0.4);
        fillLight.position.set(-3, 2, -4);
        scene.add(fillLight);

        // --- Ground (treadmill-style) ---
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x2a2a3a, roughness: 0.8 });
        const ground = new THREE.Mesh(new THREE.PlaneGeometry(12, 3), groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.5;
        ground.receiveShadow = true;
        scene.add(ground);

        // treadmill belt lines
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x4a4a5a, roughness: 0.6 });
        for (let i = -2; i <= 2; i++) {
            const line = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.02, 2.8), beltMat);
            line.position.set(i * 0.9, -0.48, 0);
            line.rotation.x = 0;
            line.receiveShadow = true;
            scene.add(line);
        }

        // --- Build low-poly humanoid (using primitives) ---
        const humanoid = new THREE.Group();
        humanoid.position.y = 0.5;

        // materials
        const skinMat = new THREE.MeshStandardMaterial({ color: 0xf4c07a, roughness: 0.7 });
        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x2a4a6a, roughness: 0.8 });
        const shirtMat = new THREE.MeshStandardMaterial({ color: 0x8a3a3a, roughness: 0.7 });
        const shoeMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.9 });

        // --- Torso ---
        const torso = new THREE.Mesh(new THREE.BoxGeometry(0.9, 1.2, 0.5), shirtMat);
        torso.position.y = 0.4;
        torso.castShadow = true;
        humanoid.add(torso);

        // --- Head ---
        const head = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.6, 0.6), skinMat);
        head.position.y = 1.25;
        head.castShadow = true;
        humanoid.add(head);

        // simple face hint (eyes)
        const eyeMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
        const eyeL = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, 0.1), eyeMat);
        eyeL.position.set(-0.15, 1.3, 0.3);
        humanoid.add(eyeL);
        const eyeR = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, 0.1), eyeMat);
        eyeR.position.set(0.15, 1.3, 0.3);
        humanoid.add(eyeR);

        // --- Arms (groups with shoulder pivot) ---
        const shoulderL = new THREE.Group();
        shoulderL.position.set(-0.55, 0.6, 0);
        const shoulderR = new THREE.Group();
        shoulderR.position.set(0.55, 0.6, 0);

        const armL = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.9, 0.25), skinMat);
        armL.position.y = -0.45;
        armL.castShadow = true;
        shoulderL.add(armL);
        const armR = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.9, 0.25), skinMat);
        armR.position.y = -0.45;
        armR.castShadow = true;
        shoulderR.add(armR);

        // hands
        const handMat = new THREE.MeshStandardMaterial({ color: 0xf4c07a });
        const handL = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.22, 0.22), handMat);
        handL.position.y = -0.9;
        shoulderL.add(handL);
        const handR = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.22, 0.22), handMat);
        handR.position.y = -0.9;
        shoulderR.add(handR);

        humanoid.add(shoulderL);
        humanoid.add(shoulderR);

        // --- Legs (groups with hip pivot) ---
        const hipL = new THREE.Group();
        hipL.position.set(-0.25, 0.0, 0);
        const hipR = new THREE.Group();
        hipR.position.set(0.25, 0.0, 0);

        const legL = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.9, 0.25), pantsMat);
        legL.position.y = -0.45;
        legL.castShadow = true;
        hipL.add(legL);
        const legR = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.9, 0.25), pantsMat);
        legR.position.y = -0.45;
        legR.castShadow = true;
        hipR.add(legR);

        // shoes
        const shoeL = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.15, 0.5), shoeMat);
        shoeL.position.set(0, -0.9, 0.1);
        hipL.add(shoeL);
        const shoeR = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.15, 0.5), shoeMat);
        shoeR.position.set(0, -0.9, 0.1);
        hipR.add(shoeR);

        humanoid.add(hipL);
        humanoid.add(hipR);

        // --- Tilt torso slightly forward when running (we'll rotate whole humanoid) ---
        scene.add(humanoid);

        // --- Animation state ---
        const clock = new THREE.Clock();
        const CYCLE = 10; // seconds

        // helper to map time to phase
        // 0-2s stand, 2-5s walk, 5-8s run, 8-10s stand
        function getPhase(t) {
            const local = t % CYCLE;
            if (local < 2) return { type: 'stand', progress: 0 };
            if (local < 5) return { type: 'walk', progress: (local - 2) / 3 };
            if (local < 8) return { type: 'run', progress: (local - 5) / 3 };
            return { type: 'stand', progress: 0 };
        }

        // --- Animation loop ---
        function animate() {
            const delta = clock.getDelta();
            const elapsed = clock.getElapsedTime();

            const phase = getPhase(elapsed);
            const t = phase.progress;

            // --- Base pose offsets ---
            let armAngleL = 0;
            let armAngleR = 0;
            let legAngleL = 0;
            let legAngleR = 0;
            let torsoLean = 0; // forward lean (rotation.x)

            if (phase.type === 'walk') {
                // walking: moderate swings, period ~1.2s (3s for 2.5 cycles)
                const cycle = t * 2.5 * Math.PI * 2; // 2.5 full swings in 3s
                armAngleL = Math.sin(cycle) * 0.6;
                armAngleR = Math.sin(cycle + Math.PI) * 0.6;
                legAngleL = Math.sin(cycle + Math.PI) * 0.5;
                legAngleR = Math.sin(cycle) * 0.5;
                torsoLean = 0.05;
            } else if (phase.type === 'run') {
                // running: faster, larger swings, slight forward lean
                const cycle = t * 4 * Math.PI * 2; // 4 full cycles in 3s
                armAngleL = Math.sin(cycle) * 1.1;
                armAngleR = Math.sin(cycle + Math.PI) * 1.1;
                legAngleL = Math.sin(cycle + Math.PI) * 0.9;
                legAngleR = Math.sin(cycle) * 0.9;
                torsoLean = 0.25;
            } else {
                // stand: all zero
            }

            // Apply rotations
            // Arms: rotate around Z axis (side view)
            shoulderL.rotation.z = armAngleL;
            shoulderR.rotation.z = armAngleR;
            // Legs: rotate around Z axis (side view)
            hipL.rotation.z = legAngleL;
            hipR.rotation.z = legAngleR;

            // Torso lean (forward = rotate X negative)
            humanoid.rotation.x = torsoLean;

            // Slight body bob for walk/run
            if (phase.type === 'walk') {
                humanoid.position.y = 0.5 + Math.sin(t * 2.5 * Math.PI * 2) * 0.03;
            } else if (phase.type === 'run') {
                humanoid.position.y = 0.5 + Math.sin(t * 4 * Math.PI * 2) * 0.06;
            } else {
                humanoid.position.y = 0.5;
            }

            // Keep feet roughly near ground (adjust leg pivot height)
            // Already fine because leg length ~0.9+shoe, hip at y=0, ground at -0.5
            // humanoid y=0.5 => hip at 0.5, leg extends to -0.4, shoe at -0.4, ground -0.5 => good

            // Render
            renderer.render(scene, camera);
            requestAnimationFrame(animate);
        }

        animate();

        // --- Resize handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
</body>
</html>
```
